import socket, struct

def dns_query(name, server='192.168.65.7', qtype=1):
    tid = 0x1234
    header = struct.pack('>HHHHHH', tid, 0x0100, 1, 0, 0, 0)
    q = b''.join(bytes([len(p)]) + p.encode() for p in name.split('.')) + b'\x00'
    q += struct.pack('>HH', qtype, 1)
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    s.settimeout(3)
    s.sendto(header + q, (server, 53))
    try:
        data, _ = s.recvfrom(4096)
    except Exception as e:
        print(server, name, 'ERR', e); return
    ancount = struct.unpack('>H', data[6:8])[0]
    print(server, name, 'rcode', data[3]&0xf, 'an', ancount, 'hex', data.hex())

for srv in ['192.168.65.7','172.30.0.1','8.8.8.8','1.1.1.1']:
    for n in ['prices.internal','commons.local']:
        dns_query(n, srv)
EOF"}

